using Microsoft.DotNet.Interactive.Formatting;
record SvgMarkup(string Content);
Formatter.Register<SvgMarkup>((v,w)=>w.Write(v.Content), "text/html");
string F(double x)=>x.ToString("0.##",CultureInfo.InvariantCulture);
string Esc(string s)=>System.Security.SecurityElement.Escape(s);
string SeriesSvg(double[] xs, double[][] ys, string[] labels, string title, string xlab, string ylab, bool logX=false) {
    const int W=800,H=360,L=80,R=30,Top=45,Bot=65;
    var xx=xs.Select(v=>logX?Math.Log10(v):v).ToArray(); double x0=xx.Min(), x1=xx.Max();
    double y0=Math.Min(0,ys.SelectMany(v=>v).Min()), y1=ys.SelectMany(v=>v).Max(); if(y1==y0)y1=y0+1;
    double X(double v)=>L+(v-x0)/(x1-x0)*(W-L-R); double Y(double v)=>H-Bot-(v-y0)/(y1-y0)*(H-Top-Bot);
    var b=new StringBuilder($"<svg xmlns='http://www.w3.org/2000/svg' width='{W}' height='{H}' viewBox='0 0 {W} {H}'><rect width='100%' height='100%' fill='white'/><text x='400' y='23' text-anchor='middle'>{Esc(title)}</text><path d='M {L} {Top} V {H-Bot} H {W-R}' stroke='black' fill='none'/>");
    for(int i=0;i<=5;i++) { double xv=x0+(x1-x0)*i/5, yv=y0+(y1-y0)*i/5; b.Append($"<text x='{F(X(xv))}' y='{H-Bot+19}' text-anchor='middle' font-size='11'>{F(logX?Math.Pow(10,xv):xv)}</text><text x='{L-8}' y='{F(Y(yv)+4)}' text-anchor='end' font-size='11'>{F(yv)}</text>"); }
    string[] couleurs={"#2455a4","#c33b31"};
    for(int j=0;j<ys.Length;j++) { var pts=string.Join(" ",xx.Select((v,i)=>$"{F(X(v))},{F(Y(ys[j][i]))}")); b.Append($"<polyline points='{pts}' fill='none' stroke='{couleurs[j%2]}' stroke-width='2'/><text x='{W-R-180}' y='{Top+15+j*18}' fill='{couleurs[j%2]}' font-size='12'>{Esc(labels[j])}</text>"); }
    b.Append($"<text x='400' y='{H-10}' text-anchor='middle'>{Esc(xlab)}</text><text transform='translate(18,180) rotate(-90)' text-anchor='middle'>{Esc(ylab)}</text></svg>");return b.ToString();
}
