bool VerifierAB(Func<Context,int,Dictionary<string,ArithExpr>,ArithExpr> candidat) {
 if(candidat==null)return false;
 foreach(int d in new[]{0,10,20,21,35,60}) {
  using var ctx=new Context(); var e=new Dictionary<string,ArithExpr>{{"r",ctx.MkRealConst("r")},{"q",ctx.MkRealConst("q")},{"w",ctx.MkRealConst("w")}};
  ArithExpr resultat=candidat(ctx,d,e);if(resultat==null)return false;
  ArithExpr attendu=ctx.MkAdd(ctx.MkMul(e["r"],ctx.MkReal(Math.Min(d,20))),ctx.MkMul(e["q"],Pos(ctx,ctx.MkSub(ctx.MkReal(d-20),e["w"]))));
  using var s=ctx.MkSolver();s.Assert(ctx.MkNot(ctx.MkEq(resultat,attendu)));if(s.Check()!=Status.UNSATISFIABLE)return false;
 }return true;
}
